     <el-option label=\"待支付\" value=\"pending\" />\n              <el-option label=\"已完成\" value=\"completed\" />\n              <el-option label=\"已取消\" value=\"cancelled\" />\n            </el-select>\n            <el-date-picker\n              v-model=\"dateRange\"\n              type=\"daterange\"\n              range-separator=\"至\"\n              start-placeholder=\"开始日期\"\n              end-placeholder=\"结束日期\"\n              style=\"margin-left: 10px;\"\n            />\n            <el-button type=\"primary\" :icon=\"Search\" style=\"margin-left: 10px;\">搜索</el-button>\n          </div>\n          \n          <!-- 表格 -->\n          <el-table :data=\"tableData\" stripe style=\"width: 100%\" v-loading=\"loading\">\n            <el-table-column prop=\"orderId\" label=\"订单号\" width=\"180\" />\n            <el-table-column prop=\"userName\" label=\"用户名\" width=\"120\" />\n            <el-table-column prop=\"productName\" label=\"商品名称\" min-width=\"200\" />\n            <el-table-column prop=\"amount\" label=\"金额\" width=\"120\">\n              <template #default=\"{ row }\">\n                <span class=\"amount\">¥{{ row.amount }}</span>\n              </template>\n            </el-table-column>\n            <el-table-column prop=\"status\" label=\"状态\" width=\"100\">\n              <template #default=\"{ row }\">\n                <el-tag :type=\"getStatusType(row.status)\">\n                  {{ getStatusText(row.status) }}\n                </el-tag>\n              </template>\n            </el-table-column>\n            <el-table-column prop=\"createTime\" label=\"创建时间\" width=\"180\" />\n            <el-table-column label=\"操作\" width=\"180\" fixed=\"right\">\n              <template #default=\"{ row }\">\n                <el-button type=\"primary\" size=\"small\" link @click=\"handleView(row)\">查看</el-button>\n                <el-button type=\"primary\" size=\"small\" link @click=\"handleEdit(row)\">编辑</el-button>\n                <el-button type=\"danger\" size=\"small\" link @click=\"handleDelete(row)\">删除</el-button>\n              </template>\n            </el-table-column>\n          </el-table>\n          \n          <!-- 分页 -->\n          <div class=\"pagination\">\n            <el-pagination\n              v-model:current-page=\"currentPage\"\n              v-model:page-size=\"pageSize\"\n              :page-sizes=\"[10, 20, 50, 100]\"\n              :total=\"total\"\n              layout=\"total, sizes, prev, pager, next, jumper\"\n              @size-change=\"handleSizeChange\"\n              @current-change=\"handleCurrentChange\"\n            />\n          </div>\n        </el-card>\n      </main>\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive } from 'vue';\nimport { ElMessage, ElMessageBox } from 'element-plus';\nimport {\n  Management, Odometer, User, Goods, ShoppingCart,\n  TrendCharts, Setting, Bell, Refresh, Search,\n  Money, Fold, Expand\n} from '@element-plus/icons-vue';\n\n// 侧边栏折叠状态\nconst isCollapsed = ref(false);\nconst activeMenu = ref('dashboard');\n\n// 切换侧边栏\nconst toggleSidebar = () => {\n  isCollapsed.value = !isCollapsed.value;\n};\n\n// 菜单选择\nconst handleMenuSelect = (index) => {\n  activeMenu.value = index;\n  ElMessage.info(`选择了: ${index}`);\n};\n\n// 用户下拉菜单\nconst handleCommand = (command) => {\n  if (command === 'logout') {\n    ElMessageBox.confirm('确定要退出登录吗？', '提示', {\n      confirmButtonText: '确定',\n      cancelButtonText: '取消',\n      type: 'warning'\n    }).then(() => {\n      ElMessage.success('已退出登录');\n    });\n  } else {\n    ElMessage.info(`点击了: ${command}`);\n  }\n};\n\n// 搜索相关\nconst searchKeyword = ref('');\nconst statusFilter = ref('');\nconst dateRange = ref([]);\n\n// 表格数据\nconst loading = ref(false);\nconst currentPage = ref(1);\nconst pageSize = ref(10);\nconst total = ref(100);\n\nconst tableData = ref([\n  {\n    orderId: 'ORD202606100001',\n    userName: '张三',\n    productName: 'iPhone 15 Pro Max 256GB',\n    amount: '9999.00',\n    s